/** Saved Java lexical loops plus independently reducible actual compiler CFG; no target Code. */
public final class SourceLexicalCycleDomain implements Opcodes {
 static Path root;
 static void need(boolean v,String s){ExecutableVerify.need(v,"actual_source_lexical_cycle_"+s);}
 static void loops(JsonElement e,Map<String,Integer> result){if(e==null)return;if(e.isJsonArray())for(var x:e.getAsJsonArray())loops(x,result);else if(e.isJsonObject()){var o=e.getAsJsonObject();if(o.has("kind")){String k=o.get("kind").getAsString();if(k.equals("structured_while")||k.equals("structured_do_while"))result.merge(k,1,Integer::sum);}for(var x:o.entrySet())loops(x.getValue(),result);}}
 static boolean hasBackward(MethodNode m){var ops=LeafSource.ops(m);for(int i=0;i<ops.size();i++)if(ops.get(i)instanceof JumpInsnNode j&&ExecutableVerify.target(m,j.label)<=i)return true;return false;}
 static Map<String,Integer> parsedSourceLoops(MethodNode q,JsonObject r)throws Exception {
  need(root!=null&&r.has("actual_saved_compiler_source_binding"),"exact_saved_compiler_source_binding_required");var b=r.getAsJsonObject("actual_saved_compiler_source_binding");Path path=root.resolve(b.get("path").getAsString());byte[] text=Files.readAllBytes(path);need(text.length==b.get("size").getAsInt()&&ExecutableVerify.hash(text).equals(b.get("sha256").getAsString()),"saved_Java_size_and_SHA");var compiler=ToolProvider.getSystemJavaCompiler();need(compiler!=null,"JDK_parser_available");var dc=new DiagnosticCollector<JavaFileObject>();var methods=new ArrayList<MethodTree>();
  try(var manager=compiler.getStandardFileManager(dc,Locale.ROOT,java.nio.charset.StandardCharsets.UTF_8)){var task=(JavacTask)compiler.getTask(null,manager,dc,List.of("-proc:none"),null,manager.getJavaFileObjectsFromPaths(List.of(path)));for(var unit:task.parse())new TreeScanner<Void,Void>(){public Void visitMethod(MethodTree m,Void p){if(m.getName().toString().equals(q.name)&&m.getParameters().size()==Type.getArgumentTypes(q.desc).length)methods.add(m);return null;}}.scan(unit,null);}
  need(dc.getDiagnostics().stream().noneMatch(d->d.getKind()==Diagnostic.Kind.ERROR)&&methods.size()==1,"unique_actual_Java_query_declaration_parses");var found=new TreeMap<String,Integer>();new TreeScanner<Void,Void>(){public Void visitWhileLoop(WhileLoopTree t,Void p){found.merge("structured_while",1,Integer::sum);return super.visitWhileLoop(t,p);}public Void visitDoWhileLoop(DoWhileLoopTree t,Void p){found.merge("structured_do_while",1,Integer::sum);return super.visitDoWhileLoop(t,p);}public Void visitForLoop(ForLoopTree t,Void p){throw new AssertionError("only_explicit_saved_while_do_grammar");}public Void visitEnhancedForLoop(EnhancedForLoopTree t,Void p){throw new AssertionError("only_explicit_saved_while_do_grammar");}}.scan(methods.get(0).getBody(),null);return found;
 }
 static boolean prove(MethodNode q,JsonObject r)throws Exception {
  if(!hasBackward(q))return false;
  var saved=new TreeMap<String,Integer>();loops(r.get("complete_expression_AST"),saved);need(!saved.isEmpty(),"explicit_saved_loop_AST_required");var parsed=parsedSourceLoops(q,r);need(saved.equals(parsed),"every_saved_while_do_count_matches_actual_Java_query");need(q.tryCatchBlocks.isEmpty(),"normal_fragment_has_no_implicit_handlers");var ops=LeafSource.ops(q);int count=ops.size();need(count>0&&count<=20000,"finite_actual_query_nodes");var successors=new ArrayList<Set<Integer>>();var predecessors=new ArrayList<Set<Integer>>();for(int i=0;i<count;i++){successors.add(new TreeSet<>());predecessors.add(new TreeSet<>());}
  for(int i=0;i<count;i++){var n=ops.get(i);var s=successors.get(i);if(n instanceof JumpInsnNode j){need(j.getOpcode()!=JSR,"no_subroutines");s.add(ExecutableVerify.target(q,j.label));if(j.getOpcode()!=GOTO)s.add(i+1);}else if(n instanceof TableSwitchInsnNode t){s.add(ExecutableVerify.target(q,t.dflt));for(var l:t.labels)s.add(ExecutableVerify.target(q,l));}else if(n instanceof LookupSwitchInsnNode t){s.add(ExecutableVerify.target(q,t.dflt));for(var l:t.labels)s.add(ExecutableVerify.target(q,l));}else if(!CFGSource.exit(n.getOpcode()))s.add(i+1);for(int t:s){need(t>=0&&t<count,"actual_instruction_edge_target");predecessors.get(t).add(i);}}
  var reachable=new BitSet(count);var todo=new ArrayDeque<Integer>();todo.add(0);while(!todo.isEmpty()){int n=todo.remove();if(reachable.get(n))continue;reachable.set(n);todo.addAll(successors.get(n));}var dom=new BitSet[count];for(int i=0;i<count;i++){dom[i]=new BitSet(count);if(reachable.get(i)){if(i==0)dom[i].set(0);else dom[i].or(reachable);}}
  boolean changed;int rounds=0;do{changed=false;need(++rounds<=count+1,"finite_dominator_fixed_point");for(int i=1;i<count;i++)if(reachable.get(i)){var next=(BitSet)reachable.clone();boolean had=false;for(int p:predecessors.get(i))if(reachable.get(p)){next.and(dom[p]);had=true;}need(had,"reachable_node_has_predecessor");next.set(i);if(!next.equals(dom[i])){dom[i]=next;changed=true;}}}while(changed);
  var backedges=new TreeMap<Integer,Set<Integer>>();for(int tail=0;tail<count;tail++)if(reachable.get(tail))for(int head:successors.get(tail))if(dom[tail].get(head))backedges.computeIfAbsent(head,k->new TreeSet<>()).add(tail);
  need(!backedges.isEmpty()&&backedges.size()<=saved.values().stream().mapToInt(Integer::intValue).sum(),"natural_loop_heads_bounded_by_saved_lexical_loops");
  for(int tail=0;tail<count;tail++)if(ops.get(tail)instanceof JumpInsnNode j&&ExecutableVerify.target(q,j.label)<=tail){int head=ExecutableVerify.target(q,j.label);need(reachable.get(tail)&&dom[tail].get(head),"each_actual_backward_jump_is_a_reachable_dominator_backedge");}
  int[] indegree=new int[count];for(int tail=0;tail<count;tail++)if(reachable.get(tail))for(int head:successors.get(tail))if(!dom[tail].get(head))indegree[head]++;var queue=new ArrayDeque<Integer>();for(int i=0;i<count;i++)if(reachable.get(i)&&indegree[i]==0)queue.add(i);int acyclic=0;while(!queue.isEmpty()){int tail=queue.remove();acyclic++;for(int head:successors.get(tail))if(!dom[tail].get(head)&&--indegree[head]==0)queue.add(head);}need(acyclic==reachable.cardinality(),"removing_only_natural_backedges_leaves_DAG_no_irreducible_cycle");
  var bodies=new TreeMap<Integer,Set<Integer>>();for(var e:backedges.entrySet()){int head=e.getKey();var body=new TreeSet<Integer>();body.add(head);var pending=new ArrayDeque<Integer>(e.getValue());while(!pending.isEmpty()){int n=pending.remove();if(body.add(n))for(int p:predecessors.get(n))if(reachable.get(p)&&p!=head)pending.add(p);}for(int n:body)if(n!=head)for(int p:predecessors.get(n))if(reachable.get(p))need(body.contains(p),"no_foreign_entry_into_natural_loop_interior");bodies.put(head,body);}
  for(var a:bodies.values())for(var b:bodies.values()){var intersection=new HashSet<>(a);intersection.retainAll(b);need(intersection.isEmpty()||a.containsAll(b)||b.containsAll(a),"natural_loop_regions_are_nested_or_disjoint");}
  var frames=new Analyzer<BasicValue>(new BasicInterpreter()).analyze("compiler/source",q);for(int head:bodies.keySet()){int raw=q.instructions.indexOf(ops.get(head));need(frames[raw]!=null&&frames[raw].getStackSize()==0,"actual_natural_loop_header_stack_empty");}
  r.add("actual_source_lexical_cycle_receipt",CFGSource.J.toJsonTree(CFGSource.map("saved_AST_loop_counts",saved,"actual_Java_parser_loop_counts",parsed,"actual_source_nodes",count,"reachable_nodes",reachable.cardinality(),"dominator_iterations",rounds,"actual_normal_backedges",backedges,"actual_nested_natural_loop_bodies",bodies,"all_cycles_reducible",true,"every_header_stack_empty",true,"source_graph_only_no_target_Code_frames",true,"original_saved_compiler_source",r.get("actual_saved_compiler_source_binding"),"termination_claimed",false)));return true;
 }
 static boolean savedLexicalSwitch(JsonObject r){if(!(r.has("bounded_natural_loop_forest")&&r.get("bounded_natural_loop_forest").getAsBoolean()&&r.has("bounded_lexical_cycle")&&r.get("bounded_lexical_cycle").getAsBoolean()&&r.has("finite_forward_switch_sites")&&r.getAsJsonArray("finite_forward_switch_sites").size()>0))return false;for(var e:r.getAsJsonArray("finite_forward_switch_sites")){var s=e.getAsJsonObject();need(s.has("all_targets_strictly_forward_and_lexically_enclosed")&&s.get("all_targets_strictly_forward_and_lexically_enclosed").getAsBoolean(),"saved_switch_lexical_contract_exact");}return true;}
 static List<JsonElement> receipts(JsonElement e){var all=new ArrayList<JsonElement>();if(e==null)return all;if(e.isJsonArray())for(var x:e.getAsJsonArray())all.addAll(receipts(x));else if(e.isJsonObject())for(var x:e.getAsJsonObject().entrySet()){if(x.getKey().equals("actual_source_lexical_cycle_receipt"))all.add(x.getValue());else all.addAll(receipts(x.getValue()));}return all;}
}
